// Shared card-building/grid-rendering so product/view/'s related-items
// grid and the listing pages don't each reimplement this. rootPrefix is
// how many "../" (or "") the calling page needs to reach the site root,
// since this same catalog is used from several directory depths.
window.SSXCatalog = {
  products: window.SSXProductCatalog,
  buildCard: function (p, rootPrefix, whiteText) {
    rootPrefix = rootPrefix || "";
    // .products-grid-6up (css/home-grid.css) sizes its direct .w-dyn-item
    // children - without this wrapper a card falls back to its natural
    // 100%-width block sizing and stacks full-width instead of sitting in
    // the grid.
    var wrapper = document.createElement("div");
    wrapper.className = "w-dyn-item";

    var card = document.createElement("a");
    card.className = "products-card-link w-inline-block";
    card.href = rootPrefix + "product/view/?name=" + encodeURIComponent(p.name);

    var imgWrap = document.createElement("div");
    imgWrap.className = "products-item-image-wrapper";
    var img = document.createElement("img");
    img.className = "products-item-image";
    img.alt = "";
    img.src = rootPrefix + p.image;
    imgWrap.appendChild(img);

    var textWrap = document.createElement("div");
    textWrap.className = "products-item-text-wrapper";

    // .products-card-link's :hover rule sets an explicit `color`, which
    // text without its own explicit color would otherwise inherit -
    // flipping from the dark default to that hover color, a visible
    // flicker. The white-text variants pin their own color so hover has no
    // visible effect on the text, matching the original behaviour (only
    // the background dims slightly on hover). Use them on dark card grids
    // (home page, all-products, category pages); the plain variants are for
    // product/view/'s "related" grid, which sits on a light background.
    var h3 = document.createElement("h3");
    h3.className = whiteText ? "heading-h4 heading-h4-white" : "heading-h4";
    h3.textContent = p.name;

    var descWrap = document.createElement("div");
    descWrap.className = "products-item-description-wrapper";
    var descClass = whiteText ? "product-list-desciption product-list-desciption-white" : "product-list-desciption";
    var descP = document.createElement("p");
    descP.className = descClass;
    descP.textContent = p.description;
    var priceP = document.createElement("p");
    priceP.className = descClass;
    // cart.js's readProductFromCard() looks for this attribute (substring
    // match on "f_price_") to find the price element when the quick-add
    // cart icon is clicked - without it the price silently reads as 0.
    priceP.setAttribute("data-wf-sku-bindings", "f_price_");
    priceP.textContent = window.SSXCart.formatMoney(p.price);
    descWrap.appendChild(descP);
    descWrap.appendChild(priceP);

    textWrap.appendChild(h3);
    textWrap.appendChild(descWrap);

    card.appendChild(imgWrap);
    card.appendChild(textWrap);
    wrapper.appendChild(card);
    return wrapper;
  },
  renderGrid: function (containerEl, products, rootPrefix, whiteText) {
    if (!containerEl) return;
    containerEl.innerHTML = "";
    products.forEach(function (p) {
      containerEl.appendChild(window.SSXCatalog.buildCard(p, rootPrefix, whiteText));
    });
    if (window.SSXCart && window.SSXCart.injectCardAddToCartButtons) {
      window.SSXCart.injectCardAddToCartButtons();
    }
  }
};
